import { Search, Menu, Bell, Moon, Sun, X, Check, CheckCheck } from 'lucide-react';
import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../../api/api';

export default function TopNav({ setSidebarOpen, onCreateNote, searchQuery, setSearchQuery }) {
  const [isDark, setIsDark] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const notifRef = useRef(null);
  const navigate = useNavigate();

  const user = (() => { try { return JSON.parse(localStorage.getItem('user')) || {}; } catch { return {}; } })();
  const initials = user.name ? user.name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2) : 'U';

  useEffect(() => {
    if (isDark) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDark]);

  useEffect(() => {
    fetchUnreadCount();
  }, []);

  useEffect(() => {
    if (showNotifications) fetchNotifications();
  }, [showNotifications]);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (notifRef.current && !notifRef.current.contains(e.target)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const fetchUnreadCount = async () => {
    try {
      const res = await api.get('/notifications/unread-count');
      setUnreadCount(res.data.count || 0);
    } catch { setUnreadCount(0); }
  };

  const fetchNotifications = async () => {
    try {
      const res = await api.get('/notifications');
      setNotifications(res.data || []);
      setUnreadCount(0);
    } catch { setNotifications([]); }
  };

  const markAllRead = async () => {
    try {
      await api.put('/notifications/read-all');
      setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
      setUnreadCount(0);
    } catch {}
  };

  const markRead = async (id) => {
    try {
      await api.put(`/notifications/${id}/read`);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
    } catch {}
  };

  const formatTime = (dateStr) => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    const diffHrs = Math.floor(diffMins / 60);
    if (diffHrs < 24) return `${diffHrs}h ago`;
    return date.toLocaleDateString();
  };

  return (
    <header className="h-16 bg-surface border-b border-border flex items-center justify-between px-4 sm:px-6 z-30 shrink-0">
      <div className="flex items-center flex-1 gap-4">
        <button
          onClick={() => setSidebarOpen(true)}
          className="md:hidden p-2 -ml-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
        >
          <Menu className="w-5 h-5" />
        </button>

        <div className="max-w-md w-full hidden sm:flex items-center relative">
          <Search className="w-4 h-4 text-slate-400 absolute left-3 pointer-events-none" />
          <input
            type="text"
            placeholder="Search notes..."
            value={searchQuery || ''}
            onChange={(e) => setSearchQuery && setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-background border border-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500 transition-all text-foreground placeholder:text-slate-400"
          />
        </div>
      </div>

      <div className="flex items-center gap-2 sm:gap-3">
        {/* Dark mode toggle */}
        <button
          onClick={() => setIsDark(!isDark)}
          className="p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"
          title="Toggle dark mode"
        >
          {isDark ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
        </button>

        {/* Notifications Bell */}
        <div className="relative" ref={notifRef}>
          <button
            onClick={() => setShowNotifications(!showNotifications)}
            className="p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors relative"
            title="Notifications"
          >
            <Bell className="w-5 h-5" />
            {unreadCount > 0 && (
              <span className="absolute top-1 right-1 w-4 h-4 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
                {unreadCount > 9 ? '9+' : unreadCount}
              </span>
            )}
          </button>

          {/* Notification Dropdown */}
          {showNotifications && (
            <div className="absolute right-0 top-12 w-80 bg-surface border border-border rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
              <div className="flex items-center justify-between px-4 py-3 border-b border-border">
                <h3 className="font-bold text-foreground text-sm">Notifications</h3>
                <div className="flex items-center gap-2">
                  {notifications.some(n => !n.isRead) && (
                    <button
                      onClick={markAllRead}
                      className="text-xs text-primary-600 hover:underline flex items-center gap-1"
                    >
                      <CheckCheck className="w-3 h-3" /> Mark all read
                    </button>
                  )}
                  <button onClick={() => setShowNotifications(false)} className="text-slate-400 hover:text-slate-600">
                    <X className="w-4 h-4" />
                  </button>
                </div>
              </div>

              <div className="max-h-80 overflow-y-auto">
                {notifications.length === 0 ? (
                  <div className="py-12 text-center">
                    <Bell className="w-8 h-8 text-slate-300 mx-auto mb-2" />
                    <p className="text-sm text-slate-400">No notifications yet</p>
                  </div>
                ) : (
                  notifications.map(notif => (
                    <div
                      key={notif.id}
                      onClick={() => markRead(notif.id)}
                      className={`px-4 py-3 border-b border-border last:border-0 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${!notif.isRead ? 'bg-primary-50/50 dark:bg-primary-900/10' : ''}`}
                    >
                      <div className="flex items-start gap-3">
                        <div className={`w-2 h-2 rounded-full mt-1.5 shrink-0 ${!notif.isRead ? 'bg-primary-500' : 'bg-transparent'}`} />
                        <div className="flex-1 min-w-0">
                          <p className="text-sm text-foreground leading-snug">{notif.message}</p>
                          <p className="text-xs text-slate-400 mt-0.5">{formatTime(notif.createdAt)}</p>
                        </div>
                        {!notif.isRead && (
                          <button
                            onClick={(e) => { e.stopPropagation(); markRead(notif.id); }}
                            className="shrink-0 text-primary-500 hover:text-primary-600"
                          >
                            <Check className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>

        {/* New Note Button */}
        {onCreateNote && (
          <button
            onClick={onCreateNote}
            className="hidden sm:flex items-center gap-1.5 bg-primary-600 hover:bg-primary-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors shadow-sm"
          >
            <span className="text-lg leading-none">+</span> New Note
          </button>
        )}

        {/* Profile Avatar */}
        <button
          onClick={() => navigate('/profile')}
          className="w-9 h-9 rounded-full bg-gradient-to-br from-primary-500 to-primary-700 flex items-center justify-center text-white font-bold text-sm cursor-pointer hover:shadow-md hover:scale-105 transition-all"
          title="View Profile"
        >
          {initials}
        </button>
      </div>
    </header>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Plus, FolderPlus, FileText, Heart, Search, Grid, List, ArrowLeft, X } from 'lucide-react';
import Sidebar from '../components/layout/Sidebar';
import TopNav from '../components/layout/TopNav';
import NoteCard from '../components/NoteCard';
import FolderCard from '../components/FolderCard';
import api from '../api/api';

export default function MyNotes() {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [folders, setFolders] = useState([]);
  const [notes, setNotes] = useState([]);
  const [noteCounts, setNoteCounts] = useState({});
  const [viewMode, setViewMode] = useState('grid');
  const [loading, setLoading] = useState(true);
  const [showCreateFolder, setShowCreateFolder] = useState(false);
  const [newFolderName, setNewFolderName] = useState('');
  const [activeFolder, setActiveFolder] = useState(null);
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  useEffect(() => {
    const folderParam = searchParams.get('folder');
    if (folderParam) {
      setActiveFolder(Number(folderParam));
    }
  }, [searchParams]);

  useEffect(() => {
    fetchData();
  }, [activeFolder]);

  const fetchData = async () => {
    setLoading(true);
    try {
      if (activeFolder) {
        const res = await api.get(`/notes/folder/${activeFolder}`);
        setNotes(res.data || []);
      } else {
        const [foldersRes, unfiledRes] = await Promise.all([
          api.get('/folders'),
          api.get('/notes/unfiled'),
        ]);
        const folderList = foldersRes.data || [];
        setFolders(folderList);
        setNotes(unfiledRes.data || []);

        // Fetch note counts for each folder
        const counts = {};
        await Promise.all(
          folderList.map(async (folder) => {
            const res = await api.get(`/notes/folder/${folder.id}`);
            counts[folder.id] = (res.data || []).length;
          })
        );
        setNoteCounts(counts);
      }
    } catch (err) {
      console.error('Failed to load notes:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateNote = async () => {
    try {
      const body = { title: 'Untitled Note', content: '' };
      if (activeFolder) body.folderId = activeFolder;
      const res = await api.post('/notes', body);
      navigate(`/notes/${res.data.id}`);
    } catch { alert('Could not create note. Are you logged in?'); }
  };

  const handleCreateFolder = async () => {
    if (!newFolderName.trim()) return;
    try {
      const res = await api.post('/folders', { name: newFolderName.trim() });
      setFolders(prev => [res.data, ...prev]);
      setNoteCounts(prev => ({ ...prev, [res.data.id]: 0 }));
      setNewFolderName('');
      setShowCreateFolder(false);
    } catch { alert('Could not create folder.'); }
  };

  const handleDeleteFolder = async (id) => {
    if (!confirm('Delete this folder? Notes will be moved to unfiled.')) return;
    try {
      await api.delete(`/folders/${id}`);
      setFolders(prev => prev.filter(f => f.id !== id));
    } catch { alert('Could not delete folder.'); }
  };

  const handleRenameFolder = async (id, name) => {
    try {
      const res = await api.put(`/folders/${id}`, { name });
      setFolders(prev => prev.map(f => f.id === id ? res.data : f));
    } catch { alert('Could not rename folder.'); }
  };

  const handleFavoriteToggle = (id) => {
    setNotes(prev => prev.map(n => n.id === id ? { ...n, isFavorite: !n.isFavorite } : n));
  };

  const activeFolderObj = folders.find(f => f.id === activeFolder);

  const filteredNotes = notes.filter(n => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return n.title?.toLowerCase().includes(q) || n.content?.toLowerCase().includes(q);
  });

  const toNoteCard = (note) => ({
    id: note.id,
    title: note.title,
    preview: note.content ? note.content.substring(0, 100) : 'Empty note',
    updatedAt: new Date(note.updatedAt).toLocaleDateString(),
    collaborators: 1,
    isFavorite: note.isFavorite,
    isDraft: note.isDraft,
  });

  return (
    <div className="h-screen flex overflow-hidden bg-background">
      <Sidebar isOpen={sidebarOpen} setIsOpen={setSidebarOpen} />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <TopNav setSidebarOpen={setSidebarOpen} onCreateNote={handleCreateNote} searchQuery={searchQuery} setSearchQuery={setSearchQuery} />

        <main className="flex-1 overflow-auto px-6 sm:px-10 py-8">
          <div className="max-w-6xl mx-auto">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center gap-3">
                {activeFolder && (
                  <button
                    onClick={() => setActiveFolder(null)}
                    className="p-2 rounded-lg text-slate-400 hover:text-foreground hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                  >
                    <ArrowLeft className="w-5 h-5" />
                  </button>
                )}
                <div>
                  <h1 className="text-2xl font-bold text-foreground">
                    {activeFolder ? (activeFolderObj?.name || 'Folder') : 'My Notes'}
                  </h1>
                  <p className="text-sm text-slate-500 mt-0.5">
                    {activeFolder ? `${filteredNotes.length} note${filteredNotes.length !== 1 ? 's' : ''}` : `${folders.length} folder${folders.length !== 1 ? 's' : ''} · ${notes.length} unfiled note${notes.length !== 1 ? 's' : ''}`}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                {/* View toggle */}
                <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                  <button onClick={() => setViewMode('grid')} className={`p-1.5 rounded-md transition-colors ${viewMode === 'grid' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600' : 'text-slate-400 hover:text-slate-600'}`}>
                    <Grid className="w-4 h-4" />
                  </button>
                  <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-colors ${viewMode === 'list' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600' : 'text-slate-400 hover:text-slate-600'}`}>
                    <List className="w-4 h-4" />
                  </button>
                </div>

                {!activeFolder && (
                  <button
                    onClick={() => setShowCreateFolder(true)}
                    className="flex items-center gap-2 px-4 py-2 border border-border rounded-xl text-sm font-medium text-foreground hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                  >
                    <FolderPlus className="w-4 h-4 text-primary-500" /> New Folder
                  </button>
                )}

                <button
                  onClick={handleCreateNote}
                  className="flex items-center gap-2 px-4 py-2 bg-primary-600 text-white rounded-xl text-sm font-medium hover:bg-primary-700 transition-colors shadow-sm"
                >
                  <Plus className="w-4 h-4" /> New Note
                </button>
              </div>
            </div>

            {/* Create Folder Modal */}
            {showCreateFolder && (
              <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
                <div className="bg-surface rounded-2xl w-full max-w-sm p-6 shadow-2xl">
                  <div className="flex items-center justify-between mb-5">
                    <h3 className="text-lg font-bold text-foreground">Create Folder</h3>
                    <button onClick={() => setShowCreateFolder(false)} className="text-slate-400 hover:text-slate-600">
                      <X className="w-5 h-5" />
                    </button>
                  </div>
                  <input
                    autoFocus
                    type="text"
                    value={newFolderName}
                    onChange={e => setNewFolderName(e.target.value)}
                    onKeyDown={e => { if (e.key === 'Enter') handleCreateFolder(); }}
                    placeholder="Folder name..."
                    className="w-full px-4 py-3 border border-border rounded-xl bg-background text-foreground text-sm focus:outline-none focus:ring-2 focus:ring-primary-500 mb-4"
                  />
                  <div className="flex gap-2">
                    <button onClick={() => setShowCreateFolder(false)} className="flex-1 px-4 py-2.5 border border-border rounded-xl text-sm text-slate-600 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
                      Cancel
                    </button>
                    <button onClick={handleCreateFolder} disabled={!newFolderName.trim()} className="flex-1 px-4 py-2.5 bg-primary-600 text-white rounded-xl text-sm font-medium hover:bg-primary-700 transition-colors disabled:opacity-50">
                      Create Folder
                    </button>
                  </div>
                </div>
              </div>
            )}

            {loading ? (
              <div className={`grid gap-4 ${viewMode === 'grid' ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4' : 'grid-cols-1'}`}>
                {[...Array(6)].map((_, i) => (<div key={i} className="h-40 bg-slate-100 dark:bg-slate-800 rounded-2xl animate-pulse" />))}
              </div>
            ) : (
              <>
                {/* Folders section (only when not in a folder) */}
                {!activeFolder && folders.length > 0 && (
                  <section className="mb-8">
                    <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-3">Folders</h2>
                    <div className={`grid gap-4 ${viewMode === 'grid' ? 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5' : 'grid-cols-1'}`}>
                      {folders.map((folder, idx) => (
                        <FolderCard
                          key={folder.id}
                          folder={folder}
                          noteCount={noteCounts[folder.id] || 0}
                          colorIndex={idx}
                          onDelete={handleDeleteFolder}
                          onRename={handleRenameFolder}
                        />
                      ))}
                    </div>
                  </section>
                )}

                {/* Notes section */}
                <section>
                  {!activeFolder && <h2 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-3">Unfiled Notes</h2>}

                  {filteredNotes.length === 0 ? (
                    <div className="text-center py-14 bg-surface border border-dashed border-border rounded-2xl">
                      <FileText className="w-10 h-10 text-slate-300 mx-auto mb-3" />
                      <p className="text-slate-500 font-medium mb-1">No notes here</p>
                      <p className="text-slate-400 text-sm mb-4">Create a new note to get started</p>
                      <button onClick={handleCreateNote} className="px-5 py-2 bg-primary-600 text-white rounded-xl text-sm font-medium hover:bg-primary-700 transition-colors">
                        + New Note
                      </button>
                    </div>
                  ) : (
                    <div className={`grid gap-4 ${viewMode === 'grid' ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4' : 'grid-cols-1'}`}>
                      {filteredNotes.map(note => (
                        <NoteCard key={note.id} note={toNoteCard(note)} onFavoriteToggle={handleFavoriteToggle} />
                      ))}
                    </div>
                  )}
                </section>
              </>
            )}
          </div>
        </main>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Share2, Sparkles, X, Save, ArrowLeft, Trash2, Bold, Italic, Heading1, Heading2, List, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';
import api from '../api/api';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';

function NoteEditor() {
  const { id } = useParams();
  const navigate = useNavigate();

  // State
  const [title, setTitle] = useState('Untitled Note');
  const [content, setContent] = useState('');
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [summary, setSummary] = useState('');
  const [isSaved, setIsSaved] = useState(true);

  // Share modal state
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEmail, setShareEmail] = useState('');
  const [sharePermission, setSharePermission] = useState('VIEW');
  const [isSharing, setIsSharing] = useState(false);
  const [shareStatus, setShareStatus] = useState(null); // { type: 'success'|'error', message: string }

  // Ref to track if it's the first load
  const isInitialMount = useRef(true);

  // Initialize Tiptap Editor
  const editor = useEditor({
    extensions: [StarterKit],
    content: '',
    onUpdate: ({ editor }) => {
      const html = editor.getHTML();
      setContent(html);
      setIsSaved(false); // Show "Saving..." immediately when user types
    },
    editorProps: {
      attributes: {
        class: 'prose prose-sm sm:prose lg:prose-lg focus:outline-none min-h-[400px] max-w-none',
      },
    },
  });

  // 1. Fetch Note Data on Load
  useEffect(() => {
    const fetchNote = async () => {
      try {
        const res = await api.get(`/notes/${id}`);
        setTitle(res.data.title || 'Untitled Note');
        setContent(res.data.content || '');
        if (editor) {
          editor.commands.setContent(res.data.content || '');
        }
      } catch (err) {
        console.error('Load failed', err);
      }
    };
    if (editor) fetchNote();
  }, [id, editor]);

  // 2. DEBOUNCED SAVE LOGIC
  // This waits 1.5 seconds after you stop typing before hitting the database
  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    const delayDebounceFn = setTimeout(async () => {
      try {
        await api.put(`/notes/${id}`, { title, content });
        setIsSaved(true);
      } catch (err) {
        console.error('Save failed', err);
      }
    }, 1500);

    return () => clearTimeout(delayDebounceFn);
  }, [title, content, id]);

  const handleDelete = async () => {
    if (window.confirm("Delete this note?")) {
      try {
        await api.delete(`/notes/${id}`);
        navigate('/dashboard');
      } catch (err) {
        console.error('Delete failed', err);
        alert("Delete failed.");
      }
    }
  };

  const handleShare = async () => {
    if (!shareEmail.trim()) return;
    setIsSharing(true);
    setShareStatus(null);
    try {
      await api.post(`/notes/${id}/share`, {
        email: shareEmail.trim(),
        permission: sharePermission,
      });
      setShareStatus({ type: 'success', message: `Note shared successfully with ${shareEmail.trim()}!` });
      setShareEmail('');
    } catch (err) {
      const msg = err.response?.data || 'Failed to share note. Please try again.';
      setShareStatus({ type: 'error', message: typeof msg === 'string' ? msg : 'Failed to share note.' });
    } finally {
      setIsSharing(false);
    }
  };

  const closeShareModal = () => {
    setShowShareModal(false);
    setShareEmail('');
    setSharePermission('VIEW');
    setShareStatus(null);
  };

  const handleGenerateSummary = async () => {
    if (!editor || editor.isEmpty) {
        alert("Please write something first.");
        return;
    }
    setIsSummarizing(true);
    try {
      // First, ensure the current content is saved to DB before summarizing
      await api.put(`/notes/${id}`, { title, content: editor.getHTML() });

      const res = await api.post(`/notes/${id}/summarize`);
      setSummary(res.data.summary);
    } catch (err) {
      console.error('AI failed', err);
      setSummary("Failed to generate summary. Check your Gemini API Key.");
    } finally {
      setIsSummarizing(false);
    }
  };

  if (!editor) return null;

  return (
    <div className="h-screen flex flex-col bg-white text-slate-900">
      {/* Header */}
      <header className="h-16 flex items-center justify-between px-6 border-b shrink-0">
        <div className="flex items-center gap-4 flex-1">
          <button onClick={() => navigate('/dashboard')} className="p-2 text-slate-400 hover:text-slate-600">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <input
            type="text"
            value={title}
            onChange={(e) => {
              setTitle(e.target.value);
              setIsSaved(false);
            }}
            className="text-xl font-bold bg-transparent border-none focus:outline-none w-full max-w-md"
          />
          <div className="text-xs font-medium">
            {isSaved ? (
                <span className="flex items-center gap-1 text-green-600"><Save className="w-3.5 h-3.5" /> Saved to cloud</span>
            ) : (
                <span className="text-amber-600 animate-pulse">Saving...</span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button onClick={handleDelete} className="p-2 text-slate-400 hover:text-red-500" title="Delete Note">
            <Trash2 className="w-5 h-5" />
          </button>
          <button
            onClick={() => setShowShareModal(true)}
            className="px-4 py-2 bg-indigo-600 text-white font-medium rounded-lg hover:bg-indigo-700 transition flex items-center gap-2"
          >
            <Share2 className="w-4 h-4" /> Share
          </button>
        </div>
      </header>

      {/* Editor Content Area */}
      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col p-8 overflow-y-auto">
          <div className="max-w-4xl mx-auto w-full">
            {/* Toolbar */}
            <div className="flex items-center gap-1 p-1 mb-6 border rounded-lg bg-slate-50 w-fit sticky top-0 z-10">
              <button
                onClick={() => editor.chain().focus().toggleBold().run()}
                className={`p-2 rounded ${editor.isActive('bold') ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-200'}`}
              >
                <Bold className="w-4 h-4" />
              </button>
              <button
                onClick={() => editor.chain().focus().toggleItalic().run()}
                className={`p-2 rounded ${editor.isActive('italic') ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-200'}`}
              >
                <Italic className="w-4 h-4" />
              </button>
              <button
                onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}
                className={`p-2 rounded ${editor.isActive('heading', { level: 1 }) ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-200'}`}
              >
                <Heading1 className="w-4 h-4" />
              </button>
              <button
                onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
                className={`p-2 rounded ${editor.isActive('heading', { level: 2 }) ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-200'}`}
              >
                <Heading2 className="w-4 h-4" />
              </button>
              <button
                onClick={() => editor.chain().focus().toggleBulletList().run()}
                className={`p-2 rounded ${editor.isActive('bulletList') ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-200'}`}
              >
                <List className="w-4 h-4" />
              </button>
            </div>

            <EditorContent editor={editor} />
          </div>
        </div>

        {/* AI Sidebar */}
        <div className="w-80 border-l bg-slate-50 p-6 flex flex-col">
          <div className="flex items-center gap-2 mb-6 text-indigo-600">
            <Sparkles className="w-5 h-5" />
            <h3 className="font-bold">AI Assistant</h3>
          </div>

          {summary ? (
            <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100">
              <div className="flex justify-between items-center mb-2">
                <h4 className="text-sm font-bold text-slate-700">Summary</h4>
                <button onClick={() => setSummary('')}><X className="w-4 h-4 text-slate-400" /></button>
              </div>
              <p className="text-sm text-slate-600 leading-relaxed">{summary}</p>
            </div>
          ) : (
            <div className="text-center mt-10">
              <Sparkles className="w-8 h-8 text-slate-400 mx-auto mb-4" />
              <p className="text-sm text-slate-500 mb-6">Let Gemini AI summarize your note.</p>
              <button
                onClick={handleGenerateSummary}
                disabled={isSummarizing || editor.isEmpty}
                className="w-full bg-slate-900 text-white font-medium py-2 rounded-lg hover:bg-slate-800 disabled:opacity-50"
              >
                {isSummarizing ? "Generating..." : "Generate Summary"}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>

    {/* Share Modal */}
    {showShareModal && (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
        <div className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl">
          {/* Modal Header */}
          <div className="flex items-center justify-between mb-5">
            <div className="flex items-center gap-2">
              <Share2 className="w-5 h-5 text-indigo-600" />
              <h3 className="text-lg font-bold text-slate-800">Share Note</h3>
            </div>
            <button
              onClick={closeShareModal}
              className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <p className="text-sm text-slate-500 mb-5">
            Enter the email address of the person you want to share <span className="font-semibold text-slate-700">"{title}"</span> with.
          </p>

          {/* Email Input */}
          <div className="mb-4">
            <label className="block text-sm font-medium text-slate-700 mb-1.5">Email address</label>
            <input
              autoFocus
              type="email"
              value={shareEmail}
              onChange={(e) => { setShareEmail(e.target.value); setShareStatus(null); }}
              onKeyDown={(e) => { if (e.key === 'Enter') handleShare(); }}
              placeholder="colleague@example.com"
              className="w-full px-4 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition"
            />
          </div>

          {/* Permission Selector */}
          <div className="mb-5">
            <label className="block text-sm font-medium text-slate-700 mb-1.5">Permission</label>
            <select
              value={sharePermission}
              onChange={(e) => setSharePermission(e.target.value)}
              className="w-full px-4 py-2.5 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 bg-white transition"
            >
              <option value="VIEW">Can view</option>
              <option value="EDIT">Can edit</option>
            </select>
          </div>

          {/* Status message */}
          {shareStatus && (
            <div className={`flex items-start gap-2 p-3 rounded-xl text-sm mb-4 ${
              shareStatus.type === 'success'
                ? 'bg-green-50 text-green-700 border border-green-200'
                : 'bg-red-50 text-red-700 border border-red-200'
            }`}>
              {shareStatus.type === 'success'
                ? <CheckCircle className="w-4 h-4 mt-0.5 shrink-0" />
                : <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
              }
              <span>{shareStatus.message}</span>
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex gap-3">
            <button
              onClick={closeShareModal}
              className="flex-1 px-4 py-2.5 border border-slate-200 rounded-xl text-sm font-medium text-slate-600 hover:bg-slate-50 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleShare}
              disabled={!shareEmail.trim() || isSharing}
              className="flex-1 px-4 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {isSharing ? (
                <><Loader2 className="w-4 h-4 animate-spin" /> Sharing...</>
              ) : (
                <><Share2 className="w-4 h-4" /> Share Note</>
              )}
            </button>
          </div>
        </div>
      </div>
    )}
  );
}

